from lib import *
E, M, S, H = 'easy', 'medium', 'sufficient', 'hard'

def vessel(h, lab_h='h', liquid=None, body=None, lab_body=None):
    f = {"kind": "vessel", "h": h, "labels": {"h": lab_h}}
    if liquid: f["labels"]["liquid"] = liquid
    if body: f["body"] = body
    if lab_body: f["labels"]["body"] = lab_body
    return f

